function recipeAppearance(
  appearance: AppearanceConfig,
  id: RecipeId,
  tuning: RecipeTuning,
): AppearanceConfig {
  const hover: Record<RecipeId, AppearanceConfig["hover"]> = {
    aurora: "none",
    gradient: "none",
    spotlight: "spotlight",
    glow: "glow",
    tilt: "tilt",
    magnetic: "magnetic",
  };
  return {
    ...appearance,
    material:
      id === "aurora" || id === "spotlight"
        ? "glass"
        : id === "gradient"
          ? "gradient"
          : "elevated",
    radius: 20,
    hover: hover[id],
    gradient: {
      ...appearance.gradient,
      kind: id === "aurora" ? "mesh" : tuning.gradient,
      angle: tuning.angle,
      intensity: tuning.intensity,
    },
    shader: {
      kind: id === "aurora" ? tuning.shader : "none",
      speed: tuning.speed,
      scale: tuning.scale,
      intensity: tuning.intensity,
      paused: tuning.paused,
    },
  };
}

