  if (id === "aurora") {
    opening = `<ShaderBackground kind=${JSON.stringify(tuning.shader)} colors={${colors}} speed={${tuning.speed}} scale={${tuning.scale}} intensity={${tuning.intensity}} paused={paused || ${config.motion === "off"}} className="rounded-2xl p-8">`;
