  .af-hover-card:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
  ),
  .af-hover-link:where(
    :disabled,
    [data-disabled],
    [aria-disabled="true"],
    [aria-busy="true"]
